#!/usr/bin/env bash
# ==============================================================================
# CivicPulse Self-Extracting Archive for Render / Cloud Deployment
# ==============================================================================
# Usage:
#   bash civicpulse_self_extracting_bundle.sh
# ==============================================================================
set -e

echo "[1/3] Decoding CivicPulse project payload..."
TMP_ZIP="civicpulse_payload.zip"

python3 -c "
import base64
with open('$0', 'r') as f:
    payload = f.read().split('__PAYLOAD_BELOW__\n')[1]
with open('civicpulse_payload.zip', 'wb') as out:
    out.write(base64.b64decode(payload.strip()))
"

echo "[2/3] Extracting project files..."
unzip -o "$TMP_ZIP"
rm -f "$TMP_ZIP"

if [ -f "build.sh" ]; then
    chmod +x build.sh
fi

echo ""
echo "=== CivicPulse extracted successfully! Ready for Render deployment. ==="
exit 0

__PAYLOAD_BELOW__

